source(file.path("helpers", "native-guard.R"))
# Numeric component/route regression tests; never compile or sample.
if(Sys.getenv('MEASUREMENTPKG_SOURCE')!='')for(f in list.files(file.path(Sys.getenv('MEASUREMENTPKG_SOURCE'),'R'),pattern='[.]R$',full.names=TRUE))source(f)else library(bmeas)
passed<-0L
ok<-function(x,label){stopifnot(isTRUE(x));passed<<-passed+1L;cat('PASS:',label,'\n')}
err<-function(expr,code){r<-tryCatch({force(expr);NULL},error=identity);ok(inherits(r,'measurement_error')&&identical(r$code,code),code)}
Q<-matrix(0,4,3);for(j in 1:3){Q[1:j,j]<-1/sqrt(j*(j+1));Q[j+1,j]<--j/sqrt(j*(j+1))}
P<-matrix(c(1,1,-1,-1)/sqrt(2),4,1);C<-matrix(c(1,-1,1,-1)/sqrt(2),4,1)
keys<-targets('accuracy','p',paste0('cell',1:8))
families<-list(Left=list(keys=keys[1:4],paradigm=P,content=C,interaction=P*C,paradigm_loadings=sqrt(2)*P,content_loadings=sqrt(2)*C),Right=list(keys=keys[5:8],paradigm=P,content=C,interaction=P*C,paradigm_loadings=sqrt(2)*P,content_loadings=sqrt(2)*C))
s<-component_covariance_structure(families,Q,'synthetic_lattice_v1','Original synthetic generic design; no M3 task names')
d<-data.frame(person=rep(paste0('synthetic_',1:3),each=8),task=rep(paste0('cell',1:8),3),successes=rep(c(1,2,3),each=8),trials=4)
b<-observe(binomial_model(),d,'person','task',fields=list(successes='successes',trials='trials'),units='count')
prior<-component_prior_set(stats::setNames(lapply(keys,function(k)logistic(0,1)),keys),student_t(3,0,.5),normal(0,1.5),normal(0,.3),normal(0,.3),normal(0,.15),cross=list(Right=normal(0,.2)),source='Explicit synthetic example')
spec<-measurement(list(accuracy=b),shared_subjects('synthetic_generic'),s,prior)
state<-list(mu=seq(-.2,.2,length.out=8),tau=seq(.3,.6,length.out=8),z_task=outer(seq_len(8),c(-.03,0,.03)),families=list(),cross=list(Right=matrix(seq(-.05,.06,length.out=9),3,3)))
for(n in names(families))state$families[[n]]<-list(base=c(-.1,.15,.05),paradigm=matrix(c(.02,-.01,.03),3,1),content=matrix(c(-.01,.04,.02),3,1),interaction=matrix(c(.01,.02,-.02),3,1))
eval<-evaluate_component_structure(s,state)
ok(nrow(eval$eta)==3&&ncol(eval$eta)==8&&s$common_total==6,'non-M3 blueprint generates generic parameter/common dimensions')
ok(max(abs(rowSums(eval$load_share)-1))<1e-12&&max(abs(diag(eval$Sigma_task)-1))<1e-12,'shares and standardized task covariance obey declared algebra')
ok(max(abs(eval$Omega_component[1:3,1:3]-diag(3)))<1e-12&&max(abs(eval$Omega_component[4:6,4:6]-diag(3)))<1e-12,'within-family common blocks stay identity')
ok(max(abs(colSums(eval$delta)))<1e-12,'individual task effects remain centered')
fake_fit<-structure(list(spec=spec),class='measurement_fit');err(ppc_plan(fake_fit,2,diagnostic_budget(2,24,48)),'E_CHECK_UNSUPPORTED')
code<-as.character(make_stan_code(spec));ok(!grepl('m3|CS_color|MU_',code),'generic renderer contains no M3 task-name dispatch')
ok(!grepl('vector[O] log_lik;',code,fixed=TRUE)&&grepl('vector[O] log_lik;',as.character(make_stan_code(verification_outputs(spec,TRUE))),fixed=TRUE),'pointwise density output is explicitly requested, never default LOO preparation')
bad<-s;bad$keys<-rev(bad$keys);err(evaluate_component_structure(bad,state),'E_COMPONENT_DESIGN')
bad<-s;bad$common_total<-7L;err(evaluate_component_structure(bad,state),'E_COMPONENT_DESIGN')
badstate<-state;badstate$mu[1]<-Inf;err(evaluate_component_structure(s,badstate),'E_COMPONENT_STATE')
badstate<-state;badstate$families$Left$base<-1;err(evaluate_component_structure(s,badstate),'E_COMPONENT_STATE')
err(component_prior_set(prior$mean,prior$task_sd,prior$base,prior$paradigm,prior$content,prior$interaction,list(Right=normal(0,.2),Right=normal(0,.2)),source='bad'),'E_NAMES')
err(density_route(1,'test_lpmf',c('y','a-b'),c('int','real'),list('a-b'='p')),'E_ROUTE')
err(density_route(1,'test_lpmf',c('y','a','a'),c('int','real','real'),list(a='p')),'E_ROUTE')
one<-d[d$person=='synthetic_1',];ob<-observe(binomial_model(),one,'person','task',fields=list(successes='successes',trials='trials'),units='count')
err(measurement(list(accuracy=ob),shared_subjects('synthetic_generic'),s,prior),'E_COMPONENT_CENTERING')
# Original schema contract is optional and needs explicitly authorized external bytes.
file<-Sys.getenv('MEASUREMENTPKG_M3_RESOURCE')
if(nzchar(file)) {
  x<-expand.grid(content=1:3,route=1:3,person=c('synthetic_a','synthetic_b'),stringsAsFactors=FALSE)
  x$observation_id<-sprintf('SYN%03d',seq_len(nrow(x)));x$observation_task<-paste(x$route,x$content,sep='_')
  active<-list(c(1:4,10),c(5:7,9:10),5:10);x$counts<-x$options<-matrix(0L,nrow(x),10)
  for(o in seq_len(nrow(x))){x$counts[o,active[[x$route[o]]]]<-1L;x$options[o,active[[x$route[o]]]]<-1L}
  bindings<-m3_reference_bindings(x);model<-m3_model(file)
  block<-observe(model,x,'person','observation_task',observation_id='observation_id',fields=list(counts='counts',options='options',route='route',content='content'),units='count',parameter_bindings=bindings)
  gs<-reference_structure('csmu_exp1_memory_gpc_v1',bindings$domains,'memory');gp<-reference_priors('csmu_exp1_memory_gpc_v1',bindings$domains,'memory')
  full<-measurement(list(memory=block),shared_subjects('synthetic_full'),gs,gp)
  table<-parameter_binding_table(full)
  ok(nrow(parameter_keys(full))==27L&&nrow(table)==84L,'full M3 has explicit27-key domain and all three route arguments')
  ok(sum(table$kind=='fixed')==12L&&all(table$fixed_value[table$kind=='fixed']==100),'MU ra stays fixed predictor100 outside estimated domain')
  ok(stan_data(full)$K==15L&&structure_ir(full)$free_parameters==237L,'reference structure derives correct dimensions for N2 without changing component definitions')
  dup<-block;dup$data<-rbind(dup$data,dup$data[1,,drop=FALSE]);err(measurement(list(memory=dup),shared_subjects('synthetic_full'),gs,gp),'E_DUPLICATE_OBSERVATION')
  changed<-block;changed$data$content<-(changed$data$content%%3L)+1L;err(measurement(list(memory=changed),shared_subjects('synthetic_full'),gs,gp),'E_REFERENCE_BINDING')
  changed<-full;changed$models$memory$model$parameters$a$receives<-'theta';err(make_stan_code(changed),'E_PARAMETER_SCALE')
  badrun<-run_config(1,1,1,10,10,1,1,72,8,10,max_treedepth=6)
  err(execution_plan(full,badrun),'E_RUN_BUDGET')
  bounded<-run_config(1,1,1,10,10,1,1,72,8,10,max_treedepth=6,model_budget=reference_run_budget('csmu_exp1_memory_gpc_v1'))
  ok(execution_plan(full,bounded)$indicators==27L,'only explicit scoped reference budget permits27 parameters')
  err(run_config(1,1,1,11,10,1,1,72,8,10,max_treedepth=6,model_budget=reference_run_budget('csmu_exp1_memory_gpc_v1')),'E_RUN_BUDGET')
} else cat('SKIP: full-reference package checks require external M3 source path\n')
cat('TOTAL',passed,'component IR checks passed; no compilation or MCMC\n')
